Trading the analytically-continued sinh-Gordon coupling for a real
parameter $\theta_0$, the staircase S-matrix is
\begin{equation}
S(\theta)=
\tanh\left(\frac{\theta{-}\theta_0}{2}-\frac{i\pi}{4}\right)
\tanh\left(\frac{\theta{+}\theta_0}{2}-\frac{i\pi}{4}\right)
\label{stairS}
\end{equation}
and this leads to the following TBA equations for the pseudoenergy 
$\epsilon(\theta)$ for the system on a circle of circumference $R$\,:
\begin{equation}
\epsilon(\theta)=r\cosh\theta-\int_{{\mathbb R}}\phi_S(\theta-\theta')L(\theta')d\theta'
\label{stairTBA}
\end{equation}
where $r=M\!R$, and
\begin{equation}
L(\theta)=\ln(1+e^{-\epsilon(\theta)})\,,\quad
\phi_S(\theta)=-\frac{i}{2\pi}\frac{d}{d\theta}\ln S(\theta)\,.
\end{equation}

The ground state energy of the system is then given by
$E(R)=-\frac{\pi}{6R}\,c_{\rm eff}(r)$, where the effective central charge
$c_{\rm eff}(r)$ is
\begin{equation}
c_{\rm eff}(r)=\frac{6}{\pi^2}\int_{{\mathbb R}}r\cosh(\theta)L(\theta)\,d\theta\,.
\end{equation}

For later use we define
\begin{equation}
(x)(\theta)=
\frac
{\sinh\left(\fract{\theta}{2}+\fract{i\pi x}{2}\right)}
{\sinh\left(\fract{\theta}{2}-\fract{i\pi x}{2}\right)}~,\qquad
\phi_{(x)}(\theta)=-\frac{i}{2\pi}\frac{d}{d\theta}\ln\,(x)(\theta)=
\frac{-\sin(\pi x)/(2\pi)\,}{\cosh(\theta)-\cos(\pi x)}~,
\end{equation}
and also
\begin{equation}
\phi(\theta)=-\phi_{(\frac{1}{2})}(\theta)=\frac{1}{2\pi\cosh(\theta)}
\label{phidef}
\end{equation}
so that the staircase kernel $\phi_S(\theta)$ is
\begin{equation}
\phi_S(\theta)=\phi(\theta-\theta_0)+\phi(\theta+\theta_0)\,.
\label{phiS}
\end{equation}

Indexing the
steps by an integer $m=3$, $4$ \dots, the 
$(m{-}2)^{\rm th}$ step is found for $-(m{-}2)\theta_0/2\ll\ln(r)\ll
-(m{-}3)\theta_0/2$, and on this step, $c_{\rm eff}(r)\to c_m$ as
$\theta_0\to\infty$, where
\begin{equation}
c_m=1-\frac{6}{m(m{+}1)}
\end{equation}
is the central charge of the unitary minimal model ${\cal M}_m$.

Hence we set
\begin{equation}
E=\frac{i\theta_{b1}}{\pi}~,\qquad 
F=\frac{i\theta_{b2}}{\pi}
\end{equation}
with $\theta_{b1}$ and $\theta_{b2}$ real and, without loss of generality,
non-negative.

There is an
obvious extension of this ansatz to incorporate $n$
boundary parameters $\theta_{b1}$ \dots $\theta_{bn}$\,:
\begin{equation}
R(\theta)=\frac
{(\frac{1}{2})(\frac{3}{4}-\frac{i\theta_0}{2\pi})
(\frac{3}{4}+\frac{i\theta_0}{2\pi})}
{\prod_{k=1}^{n}
(\frac{1}{2}-\frac{i\theta_{bk}}{2\pi})(\frac{1}{2}+\frac{i\theta_{bk}}{2\pi})}
\,.
\label{Rn}
\end{equation}

There is one such boundary condition
for each irreducible highest-weight representation (\ref{hwr}), and
its boundary entropy (or $g$-function) is \cite{Affleck:1991tk}
\begin{equation}
g(m,a,b)=
\left(\frac{8}{m(m+1)}\right)^{\frac{1}{4}}\frac{\sin(\frac{a\pi}{m})
\sin(\frac{b\pi}{m+1})}{\sqrt{\sin(\frac{\pi}{m})\sin(\frac{\pi}{m+1})}}\,.
\label{gmab}
\end{equation}

Suppose
the bulk theory is near to the minimal model ${\cal M}_m$, so that
$\ln(r)$ satisfies 
\begin{equation}
-(m{-}2)\theta_0/2 \ll \ln(r)\ll -(m{-}3)\theta_0/2 \,.
\label{rrange}
\end{equation}

define
constants $x_a$ and $y_a$ by
\begin{equation}
1+x_a=
\frac{\sin^2\Bigl(\frac{\pi a}{m+1}\Bigr)}
{\sin^2\Bigl(\frac{\pi}{m+1}\Bigr)}~~,\qquad
1+y_a=
\frac{\sin^2\Bigl(\frac{\pi a}{m}\Bigr)}
{\sin^2\Bigl(\frac{\pi}{m}\Bigr)}~.

In full, the plateau values of $L(\theta)$ are
\begin{align}
\ln(1{+}x_{a}):&~~~~~~~~~~~
z_{2a-3}-\alpha/2\ll\theta\ll 
z_{2a-3}+\alpha/2\,,\qquad~~~~\, a=2\dots m{-}1\,;
\label{platx}\\[4pt]
\ln(1{+}y_{a}):&~~~\,
z_{2a-2}-(\theta_0{-}\alpha)/2\ll\theta\ll 
z_{2a-2}+(\theta_0{-}\alpha)/2\,,~~~\, a=2\dots m{-}2\,,
\label{platy}
\end{align}
and the complete sequence between $\theta=-\ln(1/r)$ and
$\theta=+\ln(1/r)$ is
\begin{equation}
\{
\,
\ln(1{+}x_{m-1}),\,
\ln(1{+}y_{m-2}),\,
\ln(1{+}x_{m-2})\,,
\ln(1{+}y_{m-3})\, \dots\,
\ln(1{+}y_{2}),\,
\ln(1{+}x_{2})
\,
\}\,.
\label{Ls}
\end{equation}

\begin{align}
\ln(1{+}x_{a}):&~~~~~~~~~~~
z_{2a-3}-\alpha/2\ll\theta\ll 
z_{2a-3}+\alpha/2\,,\qquad~~~~\, a=2\dots m{-}1\,;
\label{platx}\\[4pt]
\ln(1{+}y_{a}):&~~~\,
z_{2a-2}-(\theta_0{-}\alpha)/2\ll\theta\ll 
z_{2a-2}+(\theta_0{-}\alpha)/2\,,~~~\, a=2\dots m{-}2\,,
\label{platy}
\end{align}

When $\ln g^{\phantom o}_{0}$, $\ln g^{\phantom o}_{b1}$ and $\ln g^{\phantom o}_{b2}$
are summed, the pieces which depend on whether
$m$ is odd or even cancel, leaving the following simple result, valid 
for all values of $m$:
\begin{equation}  
\ln g^{\phantom o}_{0}+\ln g^{\phantom o}_{b1}+\ln g^{\phantom o}_{b2}=
\ln\left(\left(\frac{8}{m(m+1)}\right)^{\frac{1}{4}}
\sqrt{\sin\frac{\pi}{m}\sin\frac{\pi}{m+1}}\right)\,.
\label{lng0sum}
\end{equation}

\begin{equation}  
\ln g^{\phantom o}_{0}+\ln g^{\phantom o}_{b1}+\ln g^{\phantom o}_{b2}=
\ln\left(\left(\frac{8}{m(m+1)}\right)^{\frac{1}{4}}
\sqrt{\sin\frac{\pi}{m}\sin\frac{\pi}{m+1}}\right)\,.
\label{lng0sum}
\end{equation}

From (\ref{Ls}) and the immediately-following remarks, the
possible values of $L(\theta)$ on these intervals
are
the elements of the set
\begin{equation}
 \left\{\ln(1+x_a), \ln(1+y_b)\right\} 
\label{lxy}
\end{equation}
where the indices $a$ and $b$ lie in the ranges
\begin{equation}
a\in\{1,\cdots,m\},\;b\in\{1,\cdots,m-1\}
\label{ab}
\end{equation}
and the value of $0$, found for $|\theta|\gg\ln(1/r)$,
arises when $a$ is equal to $1$ or $m$, or $b$ is equal to $1$ or
$m{-}1$.

