\noindent {\bf (ii)}
If one of $\theta_{b1}$ or $\theta_{b2}$ lies at the centre of an $x$-type plateau
for ${\cal M}_m$, then it remains on that plateau right up to 
the moment of the bulk transition, after which it will instead lie in
the centre of a $y$-type plateau for ${\cal M}_{m-1}$.
If this centre is located at $\theta=(m-3)\theta_0/2-(s{-}2)\theta_0$, 
$2\le s\le m{-}1$, then the corresponding
value of $L(\theta)$ moves from $\ln(1{+}x_s)|_{{\cal M}_m}$ to
$\ln(1{+}y_{s-1})|_{{\cal M}_{m-1}}$\,. 
The other plateau value simply changes its designation
from $\ln(1{+}y_r)|_{{\cal M}_m}$ to
$\ln(1{+}x_r)|_{{\cal M}_{m-1}}$\,, as in case~{\bf (i)}. 
Thus the boundary condition flow is
$[x_s,y_r]|_{{\cal M}_m}\to [y_{s-1},x_r]_{{\cal M}_{m-1}}$, or
\begin{equation}
\begin{array}{cl}
(r,s) & ~~{\cal M}_m\\[4pt]
\downarrow & \\[5pt]
(s{-}1,r) & ~~{\cal M}_{m-1}
\end{array}
\label{case2}
\end{equation}
where
\begin{equation}
2\le r\le m{-}2\,,\quad
2\le s\le m{-}1\,.
\end{equation}

\noindent {\bf (iii)} 
Lastly, if both $\theta_{b1}$ and $\theta_{b2}$ are at the centres of $x$-type
plateaux for ${\cal M}_m$, say at
$(m-3)\theta_0/2-(r{-}2)\theta_0$ and
$(m-3)\theta_0/2-(s{-}2)\theta_0$ with $2\le r,s\le m{-}1$, 
then reasoning as above the boundary condition flow is
$[x_r,x_s]|_{{\cal M}_m}\to [y_{r-1},y_{s-1}]|_{{\cal M}_{m-1}}$, or
\begin{equation}
\begin{array}{cl}
(1,f)\,\&\,(1,f{+}2)\,\&\,\cdots\,\&\,(1,g) & ~~{\cal M}_{m}\\[4pt]
\downarrow & \\[5pt]
(f,1)\,\&\,(f{+}2,1)\,\&\,\cdots\,\&\,(g{-}2,1) & ~~{\cal M}_{m-1}
\end{array}
\end{equation}
where this time
\begin{equation}
f=|r{-}s|{+}1~,\quad g=m{-}|r{+}s{-}m{-}1|
\quad \mbox{and}~~ 2\le r,s \le m{-}1\,,
\end{equation}
or equivalently
\begin{equation}
1\le f<g\le m\,,\quad f-g\in 2{\mathbb Z}\,.
\end{equation}

